sys_script.script:
(function executeRule(current, previous) {

    // =====================================================
    // RESET COUNT
    // =====================================================

    current.eligibility_count = 0;

    // Required eligibility criteria
    if (!current.eligible_branches ||
        !current.minimum_cgpa ||
        current.max_backlogs === '' ||
        current.max_backlogs === null ||
        !current.mandatory_skills) {

        return;
    }

    // =====================================================
    // GET PLACEMENT DRIVE VALUES
    // =====================================================

    var selectedBranches =
        current.eligible_branches.toString().split(',');

    var minimumCGPA =
        parseFloat(current.minimum_cgpa.toString());

    var maximumBacklogs =
        parseInt(current.max_backlogs.toString(), 10);

    var mandatorySkills =
        current.mandatory_skills.toString().split(',');


    // =====================================================
    // CLEAN BRANCH LIST
    // =====================================================

    var branchList = [];

    for (var i = 0; i < selectedBranches.length; i++) {

        var branch = selectedBranches[i].trim();

        if (branch) {
            branchList.push(branch);
        }
    }


    // =====================================================
    // CLEAN SKILL LIST
    // =====================================================

    var skillList = [];

    for (var j = 0; j < mandatorySkills.length; j++) {

        var skill = mandatorySkills[j].trim();

        if (skill) {
            skillList.push(skill);
        }
    }


    if (branchList.length === 0 ||
        skillList.length === 0 ||
        isNaN(minimumCGPA) ||
        isNaN(maximumBacklogs)) {

        return;
    }


    // =====================================================
    // FIND STUDENTS
    // CGPA >= minimum CGPA
    // Backlogs <= maximum backlogs
    // =====================================================

    var studentGR =
        new GlideRecord('x_snc_college_pl_0_student');

    studentGR.addQuery(
        'cgpa',
        '>=',
        minimumCGPA
    );

    studentGR.addQuery(
        'backlogs',
        '<=',
        maximumBacklogs
    );

    studentGR.query();


    var eligibleCount = 0;


    // =====================================================
    // CHECK EACH STUDENT
    // =====================================================

    while (studentGR.next()) {

        // -------------------------------------------------
        // CHECK BRANCH
        // -------------------------------------------------

        var studentBranch =
            studentGR.getValue('branch');

        var studentBranchDisplay =
            studentGR.getDisplayValue('branch');

        var branchMatched = false;


        for (var b = 0; b < branchList.length; b++) {

            if (studentBranch == branchList[b] ||
                studentBranchDisplay == branchList[b]) {

                branchMatched = true;
                break;
            }
        }


        if (!branchMatched) {
            continue;
        }


        // -------------------------------------------------
        // CHECK MANDATORY SKILLS
        // Student must have ALL required skills
        // -------------------------------------------------

        var studentSkills =
            studentGR.getValue('skills') || '';

        var studentSkillList =
            studentSkills.split(',');

        var hasAllSkills = true;


        for (var s = 0; s < skillList.length; s++) {

            var requiredSkill =
                skillList[s];

            var hasSkill = false;


            for (var ss = 0;
                 ss < studentSkillList.length;
                 ss++) {

                if (
                    studentSkillList[ss].trim() ==
                    requiredSkill
                ) {

                    hasSkill = true;
                    break;
                }
            }


            // Student is missing one mandatory skill
            if (!hasSkill) {

                hasAllSkills = false;
                break;
            }
        }


        // -------------------------------------------------
        // STUDENT IS ELIGIBLE
        // -------------------------------------------------

        if (hasAllSkills) {
            eligibleCount++;
        }
    }


    // =====================================================
    // SET FINAL ELIGIBILITY COUNT
    // =====================================================

    current.eligibility_count = eligibleCount;


})(current, previous);
